// CSD_RATIONALE_BEGIN
// Attempt 65 regressed from the best (53.3%, attempt 61) to 45.7%.
// The guidance change ("never use AS aliases / short aliases") in attempt 65
// demonstrably hurt accuracy by 7.7pp. Guidance additions have consistently
// hurt this 4B model.
//
// Root cause analysis of the 163 semantic failures:
//   (a) Wrong SQL structure: "most recent" → MAX instead of ORDER BY LIMIT 1.
//   (b) Wrong join/filter logic: JOIN+HAVING instead of WHERE+subquery.
//   (c) Repetition loops: column lists repeated many times.
//
// These are SQL LOGIC errors, not identifier grounding errors. The failing
// examples all use correct column/table names. RegenerateUnitOnGroundingFailure
// helps with identifier hallucination but cannot fix SQL logic errors. Worse,
// its rollback-and-penalize mechanism can disrupt natural SQL structure when
// it incorrectly penalizes a valid identifier.
//
// Hypothesis for this attempt: Use ConstrainedGeneration (hard parser mask,
// no grounding rollbacks) for the fresh-span case. This lets the LM's natural
// distribution drive SQL structure (SELECT, WHERE, ORDER BY, LIMIT) without
// rollback distortions. For the rare non-empty currentConstrained entry, fall
// back to RegenerateUnitOnGroundingFailure for continuity.
//
// Guidance: Revert to attempt 61's proven short guidance (2 sentences).
// Phase structure: identical to attempt 61.
//   Phase 1: ≤5 free steps for preamble.
//   Phase 2: OpenConstrainedSpan if not inside.
//   Phase 3: If currentConstrainedOut==[]: ConstrainedGeneration(sqlBudget).
//            Else: RegenerateUnitOnGroundingFailure(sqlBudget,5,50).
//   Phase 4: CloseConstrainedSpan or CloseSpanWithinBudget(80).
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 (parser_validity):
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
// Phase 1 preamble: Loop guard !insideConstrainedOut keeps the implication
//   vacuous throughout. The only flip to true occurs when RenderedEndsWith
//   fires, simultaneously setting currentConstrainedOut := []; IsValidPrefix([])
//   holds by the method precondition. EOS break leaves insideConstrainedOut
//   false, so the implication is vacuous.
//
// Phase 2 OpenConstrainedSpan: Only runs when !insideConstrainedOut.
//   Postcondition sets currentConstrainedOut := []; IsValidPrefix([]) holds
//   by precondition. Afterward insideConstrainedOut is true.
//
// Phase 3 ConstrainedGeneration branch (|currentConstrainedOut|==0):
//   ConstrainedGeneration loops ConstrainedStep which hard-masks to
//   parser-valid tokens; the accumulated prefix constrainedGenerated is
//   therefore parser-valid. We assign currentConstrainedOut := constrainedGenerated,
//   re-establishing the invariant. insideConstrainedOut remains true.
//
// Phase 3 RegenerateUnitOnGroundingFailure branch (|currentConstrainedOut|>0):
//   Postcondition guarantees resultConstrained is always parser-valid.
//   We assign currentConstrainedOut := resultConstrained. Invariant holds.
//
// Phase 4a CloseConstrainedSpan: Sets insideConstrainedOut := false, making
//   the implication vacuously true; clears currentConstrainedOut := [].
//
// Phase 4b CloseSpanWithinBudget: Postcondition directly guarantees
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut).
//
// Invariant 2 (progress): |generated| <= |generatedPrefix| + steps
//
// Phase 1: UnconstrainedStep increments steps by 1; appends 0 (EOS) or 1
//   (non-EOS) token. Invariant preserved each iteration (growth ≤ budget).
//
// Phase 2: OpenConstrainedSpan appends exactly 1 "<<" token; steps += 1.
//   Growth equals budget consumed. Invariant preserved.
//
// Phase 3 ConstrainedGeneration: Each ConstrainedStep produces at most 1
//   visible token; EOS and budget-exceeded paths produce 0. Thus
//   |constrainedGenerated| ≤ sqlBudget. After update:
//   |generated| = |old_generated| + |constrainedGenerated| ≤
//   |generatedPrefix| + old_steps + sqlBudget = |generatedPrefix| + new_steps.
//
// Phase 3 RegenerateUnitOnGroundingFailure: By its cost contract, it uses at
//   most sqlBudget token-steps; each step grows resultConstrained by at most 1
//   token (rejected/rolled-back tokens consume budget without growing output),
//   so |resultConstrained| ≤ sqlBudget.
//   |generated| = |stablePrefix| + |resultConstrained|
//              ≤ (|old_generated| - |currentConstrainedOut|) + sqlBudget
//              ≤ |old_generated| + sqlBudget = |generatedPrefix| + new_steps.
//
// Phase 4a: CloseConstrainedSpan +1 step, appends at most 1 ">>" token (≤1:1).
// Phase 4b: CloseSpanWithinBudget postcondition: |generatedOut| ≤ |generated|
//   + closeBudget; steps += closeBudget; invariant preserved by transitivity.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Output SQL: <<query>> where query is a valid SQL SELECT statement using ONLY the exact table and column names from the provided schema. The SQL must be placed between << and >>. No explanation, no markdown, no aliases not in the schema.");

var steps: nat := 0;

// Phase 1: Short preamble (at most 5 steps) to let model emit "SQL: <<" naturally
while steps < maxSteps && steps < 5 && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  } else {
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }
}

// Phase 2: Force "<<" if not already inside constrained span
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3: SQL generation under hard parser control
if insideConstrainedOut && steps < maxSteps {
  var remaining := maxSteps - steps;
  if remaining >= 2 {
    var sqlBudget: nat := remaining - 1;
    if |currentConstrainedOut| == 0 {
      // Fresh span: ConstrainedGeneration for natural, undistorted SQL
      var constrainedPrompt := prompt + generated;
      var constrainedGenerated, terminatedByEos := helpers.ConstrainedGeneration(
        lm, parser, constrainedPrompt, sqlBudget, eosToken
      );
      generated := generated + constrainedGenerated;
      currentConstrainedOut := constrainedGenerated;
    } else {
      // Continuing from non-empty prior state: grounding-aware generation
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var resultConstrained := helpers.RegenerateUnitOnGroundingFailure(
        lm, parser, constrainedPrompt, currentConstrainedOut, eosToken, sqlBudget, 5, 50
      );
      var stablePrefix := generated[..|generated| - |currentConstrainedOut|];
      generated := stablePrefix + resultConstrained;
      currentConstrainedOut := resultConstrained;
    }
    steps := steps + sqlBudget;
  }
}

// Phase 4: Close the constrained span
if insideConstrainedOut && steps < maxSteps {
  if parser.IsCompletePrefix(currentConstrainedOut) {
    var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
  } else {
    var remaining := maxSteps - steps;
    var closeBudget: nat;
    if remaining <= 80 {
      closeBudget := remaining;
    } else {
      closeBudget := 80;
    }
    var cg, ci, cc := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + closeBudget;
  }
}

cost := steps;

